const annualSecondarySvt6eExtensionUnits = <AnnualSecondarySvtUnit>[
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:6,title:'Les déplacements des animaux',lessonId:'core_svt_6e_locomotion',lessonTitle:'Comparer les modes de locomotion animale',summary:'Relier les organes de déplacement au milieu de vie et au mode de locomotion.',content:'Les animaux se déplacent de différentes façons : marche, course, saut, nage, reptation ou vol. Les organes locomoteurs sont adaptés au déplacement et au milieu : pattes, nageoires, ailes ou corps allongé. Pour comparer deux animaux, on décrit leur milieu, leurs organes et le mouvement observé. Une observation doit être précise et respecter l’animal.',keyPoints:['Les modes de locomotion sont variés','Les organes locomoteurs sont adaptés au milieu','Observer sans blesser ni déranger'],exercises:[
    Exercise(id:'core_svt_6e_loco1',lessonId:'core_svt_6e_locomotion',question:'Quel organe aide principalement le poisson à nager ?',options:['Les nageoires','Les ailes','Les sabots'],correctIndex:0,explanation:'Les nageoires contribuent à la propulsion et à la direction du poisson.'),
    Exercise(id:'core_svt_6e_loco2',lessonId:'core_svt_6e_locomotion',question:'Le mode de déplacement d’un oiseau en vol est…',options:['Le vol','La reptation','La marche uniquement'],correctIndex:0,explanation:'Les ailes permettent à de nombreux oiseaux de voler.'),
    Exercise(id:'core_svt_6e_loco3',lessonId:'core_svt_6e_locomotion',question:'Pour comparer la locomotion, on observe…',options:['Le milieu, les organes et le mouvement','Seulement la couleur','Le nom sans observer'],correctIndex:0,explanation:'Ces critères permettent une comparaison scientifique.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:7,title:'Vaccination et prévention',lessonId:'core_svt_6e_vaccination',lessonTitle:'Comprendre le rôle de la vaccination',summary:'Expliquer comment la vaccination prépare les défenses immunitaires et participe à la prévention.',content:'Le système immunitaire protège l’organisme contre certains agents infectieux. La vaccination présente au système immunitaire un antigène ou une instruction permettant de le reconnaître sans provoquer la maladie visée de la même manière qu’une infection naturelle. Elle prépare une réponse et peut réduire le risque de maladie grave. Les vaccins et leur calendrier relèvent des recommandations des professionnels de santé.',keyPoints:['Le système immunitaire reconnaît des agents infectieux','La vaccination prépare une réponse immunitaire','Suivre les recommandations de santé'],exercises:[
    Exercise(id:'core_svt_6e_vac1',lessonId:'core_svt_6e_vaccination',question:'La vaccination contribue surtout à…',options:['Préparer les défenses immunitaires','Remplacer tous les aliments','Faire disparaître les organes'],correctIndex:0,explanation:'Elle prépare le système immunitaire à reconnaître un agent ciblé.'),
    Exercise(id:'core_svt_6e_vac2',lessonId:'core_svt_6e_vaccination',question:'Qui peut renseigner sur le calendrier vaccinal ?',options:['Un professionnel de santé','Une publicité sans source','Un camarade au hasard'],correctIndex:0,explanation:'Les professionnels de santé s’appuient sur les recommandations officielles.'),
    Exercise(id:'core_svt_6e_vac3',lessonId:'core_svt_6e_vaccination',question:'La vaccination est une mesure de…',options:['Prévention','Pollution','Locomotion'],correctIndex:0,explanation:'Elle fait partie des moyens de prévention de certaines maladies.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:8,title:'Prévention des risques liés aux drogues',lessonId:'core_svt_6e_drugs',lessonTitle:'Identifier les risques de l’usage des drogues',summary:'Comprendre que certaines substances peuvent modifier le fonctionnement du cerveau et nuire à la santé.',content:'Une drogue est une substance qui agit sur le système nerveux et peut modifier les perceptions, l’humeur ou le comportement. Certaines substances peuvent entraîner une dépendance et affecter la mémoire, l’attention, la santé et les relations sociales. Les médicaments ne doivent être utilisés que selon les indications d’un professionnel ou d’un adulte responsable. Face à une pression, il est important de refuser, de s’éloigner et de demander de l’aide à un adulte de confiance.',keyPoints:['Certaines substances agissent sur le système nerveux','Risques : dépendance et atteintes à la santé','Refuser une substance inconnue et demander de l’aide'],exercises:[
    Exercise(id:'core_svt_6e_dr1',lessonId:'core_svt_6e_drugs',question:'Certaines drogues peuvent agir sur…',options:['Le système nerveux','Les roches uniquement','La lumière solaire'],correctIndex:0,explanation:'Ces substances peuvent modifier le fonctionnement du système nerveux.'),
    Exercise(id:'core_svt_6e_dr2',lessonId:'core_svt_6e_drugs',question:'Que faire si quelqu’un propose une substance inconnue ?',options:['Refuser et prévenir un adulte de confiance','La goûter','La prendre pour faire plaisir'],correctIndex:0,explanation:'Refuser et demander de l’aide protège la santé et la sécurité.'),
    Exercise(id:'core_svt_6e_dr3',lessonId:'core_svt_6e_drugs',question:'Un risque possible de certaines substances est…',options:['La dépendance','La croissance des plantes','La formation des roches'],correctIndex:0,explanation:'Certaines substances peuvent provoquer une dépendance.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:9,title:'Prévention des infections sexuellement transmissibles',lessonId:'core_svt_6e_sti',lessonTitle:'Connaître les IST et les moyens de prévention',summary:'Définir les IST, rappeler les modes de transmission et l’importance de la prévention et du recours aux soins.',content:'Les infections sexuellement transmissibles (IST) sont des infections qui peuvent se transmettre notamment lors de contacts sexuels. Certaines peuvent aussi se transmettre par le sang ou de la mère à l’enfant. Elles ne sont pas toujours visibles : une personne peut être infectée sans symptôme. La prévention repose sur l’information fiable, les moyens de protection adaptés, le dépistage et les soins auprès de professionnels de santé. Il faut éviter la stigmatisation et respecter la confidentialité.',keyPoints:['Une IST peut exister sans symptôme visible','La prévention inclut information, protection et dépistage','Demander conseil à un professionnel de santé'],exercises:[
    Exercise(id:'core_svt_6e_sti1',lessonId:'core_svt_6e_sti',question:'Une IST peut-elle être présente sans signe visible ?',options:['Oui','Non, jamais','Seulement chez les animaux'],correctIndex:0,explanation:'Certaines IST peuvent être asymptomatiques.'),
    Exercise(id:'core_svt_6e_sti2',lessonId:'core_svt_6e_sti',question:'Pour obtenir une information fiable sur les IST, il faut…',options:['Consulter un professionnel de santé ou une source sanitaire fiable','Se fier aux rumeurs','Éviter toute question'],correctIndex:0,explanation:'Les professionnels et sources sanitaires donnent des informations adaptées.'),
    Exercise(id:'core_svt_6e_sti3',lessonId:'core_svt_6e_sti',question:'Une personne concernée doit être…',options:['Respectée et orientée vers les soins','Ridiculisée','Exclue de l’école'],correctIndex:0,explanation:'Le respect et l’accès aux soins sont essentiels ; la stigmatisation nuit à la prévention.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:10,title:'Prévention du paludisme',lessonId:'core_svt_6e_malaria',lessonTitle:'Comprendre la transmission et la prévention du paludisme',summary:'Identifier le rôle du moustique vecteur et les mesures de prévention.',content:'Le paludisme est une maladie causée par un parasite transmis à l’être humain par la piqûre de certains moustiques Anopheles infectés. La prévention comprend l’utilisation correcte de moustiquaires imprégnées, la réduction des lieux de reproduction des moustiques et le recours rapide aux services de santé en cas de fièvre dans une zone où le paludisme circule. Le diagnostic et le traitement doivent être réalisés selon les recommandations sanitaires.',keyPoints:['Le paludisme est causé par un parasite','Transmission par certains moustiques Anopheles','Moustiquaires, lutte antivectorielle et soins rapides'],exercises:[
    Exercise(id:'core_svt_6e_mal1',lessonId:'core_svt_6e_malaria',question:'Le paludisme est transmis principalement par…',options:['La piqûre d’un moustique Anopheles infecté','Le toucher d’un cahier','Le vent seul'],correctIndex:0,explanation:'Le parasite du paludisme est transmis par certains moustiques Anopheles.'),
    Exercise(id:'core_svt_6e_mal2',lessonId:'core_svt_6e_malaria',question:'Quel moyen aide à prévenir les piqûres pendant le sommeil ?',options:['Une moustiquaire imprégnée correctement utilisée','Un récipient d’eau ouvert','Des déchets près du lit'],correctIndex:0,explanation:'Une moustiquaire imprégnée réduit l’exposition aux moustiques.'),
    Exercise(id:'core_svt_6e_mal3',lessonId:'core_svt_6e_malaria',question:'En zone de paludisme, une fièvre doit conduire à…',options:['Consulter rapidement un service de santé','Prendre un médicament au hasard','Attendre toujours plusieurs semaines'],correctIndex:0,explanation:'Un diagnostic rapide permet un traitement adapté.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:11,title:'Élevage et soins aux animaux',lessonId:'core_svt_6e_husbandry',lessonTitle:'Appliquer les connaissances à l’élevage',summary:'Relier les besoins des animaux d’élevage à leur alimentation, leur habitat et leur santé.',content:'Les animaux d’élevage ont besoin d’une alimentation adaptée, d’eau propre, d’un abri convenable et de soins. Un élevage responsable maintient les locaux propres, limite le stress, observe les animaux et sollicite un agent vétérinaire en cas de maladie. Les pratiques d’élevage doivent respecter le bien-être animal et éviter la contamination de l’eau et du sol.',keyPoints:['Alimentation et eau adaptées','Abri, hygiène et observation','Conseil vétérinaire en cas de maladie','Respect du bien-être animal et de l’environnement'],exercises:[
    Exercise(id:'core_svt_6e_elev1',lessonId:'core_svt_6e_husbandry',question:'Un animal d’élevage a besoin…',options:['D’eau propre et d’une alimentation adaptée','De déchets toxiques','D’un abri toujours sale'],correctIndex:0,explanation:'L’eau propre et l’alimentation adaptée sont essentielles.'),
    Exercise(id:'core_svt_6e_elev2',lessonId:'core_svt_6e_husbandry',question:'En cas de maladie d’un animal, il faut…',options:['Demander conseil à un agent vétérinaire','Administrer n’importe quel produit','Cacher les symptômes'],correctIndex:0,explanation:'Un professionnel peut identifier la maladie et recommander des soins adaptés.'),
    Exercise(id:'core_svt_6e_elev3',lessonId:'core_svt_6e_husbandry',question:'Un élevage responsable doit…',options:['Respecter le bien-être animal et l’hygiène','Polluer les points d’eau','Priver les animaux d’eau'],correctIndex:0,explanation:'Le bien-être, l’hygiène et la protection de l’environnement sont nécessaires.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:12,title:'La reproduction ovipare chez la poule',lessonId:'core_svt_6e_oviparity',lessonTitle:'Décrire la reproduction ovipare',summary:'Définir l’oviparité et décrire les principales étapes du développement de la poule.',content:'Un animal ovipare pond des œufs dans lesquels l’embryon se développe. Chez la poule, après fécondation, l’embryon se développe dans l’œuf. L’incubation fournit des conditions de température adaptées. Le poussin sort de l’œuf au moment de l’éclosion. Un œuf non fécondé ne donne pas de poussin.',keyPoints:['Oviparité : développement dans un œuf pondu','La fécondation est nécessaire au développement d’un poussin','Incubation puis éclosion'],exercises:[
    Exercise(id:'core_svt_6e_ovi1',lessonId:'core_svt_6e_oviparity',question:'Un animal ovipare…',options:['Pond des œufs','Porte toujours son petit dans l’utérus','Ne se reproduit pas'],correctIndex:0,explanation:'L’oviparité se caractérise par la ponte d’œufs.'),
    Exercise(id:'core_svt_6e_ovi2',lessonId:'core_svt_6e_oviparity',question:'Un poussin se développe dans…',options:['Un œuf fécondé','Une pierre','Une feuille sèche'],correctIndex:0,explanation:'Le développement embryonnaire du poussin se déroule dans un œuf fécondé.'),
    Exercise(id:'core_svt_6e_ovi3',lessonId:'core_svt_6e_oviparity',question:'L’éclosion correspond…',options:['À la sortie du poussin de l’œuf','À la ponte d’un œuf vide','À la croissance d’une plante'],correctIndex:0,explanation:'L’éclosion est la sortie du jeune de l’œuf.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:13,title:'La reproduction vivipare chez l’être humain',lessonId:'core_svt_6e_viviparity',lessonTitle:'Décrire la reproduction vivipare',summary:'Définir la viviparité et présenter le développement prénatal de façon scientifique et adaptée.',content:'Chez l’être humain, le développement du nouvel être commence après la fécondation. L’embryon puis le fœtus se développe dans l’utérus pendant la grossesse. Il reçoit les éléments nécessaires par l’intermédiaire du placenta et du cordon ombilical. Après la durée de la grossesse, l’accouchement permet la naissance. La grossesse et la santé reproductive nécessitent un suivi par des professionnels de santé.',keyPoints:['Viviparité : développement dans l’organisme maternel','Développement dans l’utérus pendant la grossesse','Placenta et cordon ombilical assurent des échanges','Suivi de grossesse par des professionnels'],exercises:[
    Exercise(id:'core_svt_6e_viv1',lessonId:'core_svt_6e_viviparity',question:'Chez l’être humain, le développement prénatal se déroule dans…',options:['L’utérus','L’estomac','Les poumons'],correctIndex:0,explanation:'L’embryon puis le fœtus se développe dans l’utérus.'),
    Exercise(id:'core_svt_6e_viv2',lessonId:'core_svt_6e_viviparity',question:'Le placenta participe notamment…',options:['Aux échanges entre la mère et le fœtus','À la digestion des aliments dans la bouche','À la locomotion'],correctIndex:0,explanation:'Le placenta permet des échanges nécessaires au développement.'),
    Exercise(id:'core_svt_6e_viv3',lessonId:'core_svt_6e_viviparity',question:'Le suivi de grossesse est assuré par…',options:['Des professionnels de santé','Des conseils anonymes sans source','Des animaux'],correctIndex:0,explanation:'Le suivi médical accompagne la santé de la mère et du fœtus.'),
  ]),
];
